{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "treat this as a negotiable cap for general warranties only, not the default for all obligations."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Seek lower thresholds and a tipping basket"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "seek at least 24 months for general warranties"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "separate capacity, authority, title and encumbrance warranties from the general regime; seek a cap of at least 100% of price"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Fraud, fraudulent misrepresentation and deliberate concealment, without indirectly excluding responsibility through an unduly narrow attribution rule."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket public-record and data-room disclosure, or tightly delimit any agreed exceptions."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "delete the exclusion."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Do not allow Seller to deem the condition satisfied by delivery alone."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Repay through the completion funds flow and obtain effective releases of all relevant security and guarantees at Completion."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Expressly allocate the agreed bonus cost and applicable superannuation, payroll tax and other on-costs to Seller economics."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Broaden the indemnity to losses from the identified ownership/payment defect, including relevant third-party claims and remediation costs"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require preservation of evidence, investigation of access and scope, containment and remediation, and assessment of applicable privacy, contractual and notification obligations."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Seek consent controls over material new commitments and a price adjustment or specific remedy only where the facts and agreed economics support one."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "general warranties must not swallow title, tax, specific indemnities, payment obligations or fraud protections."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "The register is relevant evidence, not complete title diligence."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Neither should simply be treated as “settled” under the general regime."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

